<?php
declare(strict_types=1);
namespace App\Tests\Cms;
use App\Cms\CmsPagePublicationChecker; use App\Entity\Channel\Channel; use App\Entity\Cms\{CmsLayout,CmsPage,CmsPageTranslation}; use PHPUnit\Framework\TestCase;
final class CmsPagePublicationCheckerTest extends TestCase { private function page(Channel $channel):CmsPage{$layout=new CmsLayout();$layout->setName('Standard');$page=new CmsPage();$page->setLayout($layout);$page->setStatus(CmsPage::STATUS_PUBLISHED);$page->addChannel($channel);$translation=new CmsPageTranslation();$translation->setLocale('de_DE');$translation->setTitle('Support');$translation->setSlug('support');$page->addTranslation($translation);return $page;} public function testExactChannelLocaleAndScheduleAreRequired():void{$de=new Channel();$at=new Channel();$page=$this->page($de);$checker=new CmsPagePublicationChecker();$now=new \DateTimeImmutable('2026-09-03 12:00:00');self::assertTrue($checker->isVisible($page,$de,'de_DE',$now));self::assertFalse($checker->isVisible($page,$at,'de_DE',$now));self::assertFalse($checker->isVisible($page,$de,'de_AT',$now));$page->setPublishAt($now->modify('+1 hour'));self::assertFalse($checker->isVisible($page,$de,'de_DE',$now));$page->setPublishAt(null);$page->setUnpublishAt($now);self::assertFalse($checker->isVisible($page,$de,'de_DE',$now));} public function testDraftAndDisabledAreHidden():void{$channel=new Channel();$page=$this->page($channel);$checker=new CmsPagePublicationChecker();foreach([CmsPage::STATUS_DRAFT,CmsPage::STATUS_DISABLED] as $status){$page->setStatus($status);self::assertFalse($checker->isVisible($page,$channel,'de_DE'));}} }
